// NIST SP 800-22 Rev. 1a worked examples. Inputs are the publication's example
// strings, or the binary expansions of pi and e (test/lab/fixtures, regenerated by
// scripts/make-nist-constants.mjs). Expected values are the published ones.
import test from 'node:test';
import assert from 'node:assert';
import fs from 'fs';
import * as N from '../../lab/core/nist.js';
import { Xoshiro128ss } from '../../lab/core/prng.js';

const FIX = new URL('./fixtures/', import.meta.url);
const pi = (n) => N.bitsFromBytes(fs.readFileSync(new URL('pi.bin', FIX)), n);
const e = (n) => N.bitsFromBytes(fs.readFileSync(new URL('e.bin', FIX)), n);
const S = N.bitsFromString;
const near = (actual, expected, digits = 6, label = '') =>
  assert.ok(Math.abs(actual - expected) < 0.5 * 10 ** -digits, `${label} ${actual} != ${expected}`);

const E1M = e(1000000);

test('reference inputs: pi and e expansions match the publication', () => {
  assert.strictEqual(Array.from(pi(100)).join(''), '1100100100001111110110101010001000100001011010001100001000110100110001001100011001100010100010111000');
  let x = 0;
  const b = e(60);
  for (let i = 2; i < 60; i++) if (b[i]) x += 2 ** (1 - i);
  near(2 + x, Math.E, 15, 'e');
});

test('2.1 frequency (monobit)', () => {
  near(N.frequency(S('1011010101')).pValues[0], 0.527089);
  const r = N.frequency(pi(100));
  assert.strictEqual(r.stats.sum, -16);
  near(r.pValues[0], 0.109599);
});

test('2.2 frequency within a block', () => {
  near(N.blockFrequency(S('0110011010'), 3).pValues[0], 0.801252);
  const r = N.blockFrequency(pi(100), 10);
  near(r.stats.chi2, 7.2);
  near(r.pValues[0], 0.706438);
});

test('2.3 runs', () => {
  near(N.runs(S('1001101011')).pValues[0], 0.147232);
  const r = N.runs(pi(100));
  assert.strictEqual(r.stats.vObs, 52);
  near(r.pValues[0], 0.500798);
});

test('2.4 longest run of ones in a block', () => {
  const r = N.longestRun(S('11001100000101010110110001001100111000000000001001001101010100010001001111010110100000001101011111001100111001101101100010110010'), 8);
  assert.deepStrictEqual(r.stats.nu, [4, 9, 3, 0]);
  near(r.stats.chi2, 4.882605);
  near(r.pValues[0], 0.180598);
});

test('2.5 binary matrix rank (first 100,000 bits of e)', () => {
  const r = N.matrixRank(e(100000));
  assert.deepStrictEqual([r.stats.N, r.stats.f32, r.stats.f31, r.stats.rest], [97, 23, 60, 14]);
  near(r.stats.chi2, 1.2619656, 7);
  near(r.pValues[0], 0.532069);
});

test('2.6 discrete Fourier transform (first 100 bits of e)', () => {
  const r = N.spectral(e(100));
  assert.strictEqual(r.stats.n1, 46);
  near(r.stats.n0, 47.5);
  near(r.stats.d, -1.376494);
  near(r.pValues[0], 0.168669);
});

test('FFT for non power-of-two lengths agrees with a direct DFT', () => {
  const x = Float64Array.from(e(1000), (b) => (b ? 1 : -1));
  const fast = N.dftMagnitudes(x, 500);
  for (let j = 0; j < 500; j += 37) {
    let re = 0, im = 0;
    for (let k = 0; k < 1000; k++) { re += x[k] * Math.cos(2 * Math.PI * j * k / 1000); im -= x[k] * Math.sin(2 * Math.PI * j * k / 1000); }
    near(fast[j], Math.hypot(re, im), 9, 'j=' + j);
  }
});

test('2.7 non-overlapping template matching', () => {
  const r = N.nonOverlappingTemplate(S('10100100101110010110'), [[0, 0, 1]], 2);
  assert.deepStrictEqual(r.stats.counts[0], [2, 1]);
  near(r.stats.mu, 1);
  near(r.stats.sigma2, 0.46875);
  near(r.pValues[0], 0.344154);
});

test('aperiodic template counts match the publication (m = 2..10)', () => {
  assert.deepStrictEqual([2, 3, 4, 5, 6, 7, 8, 9, 10].map((m) => N.aperiodicTemplates(m).length), [2, 4, 6, 12, 20, 40, 74, 148, 284]);
});

test('2.8 overlapping template probabilities are the exact ones of section 3.8', () => {
  const pi = N.overlappingProbabilities(new Array(9).fill(1), 1032, 5);
  [0.364091, 0.185659, 0.139381, 0.100571, 0.070432, 0.139865].forEach((v, i) => near(pi[i], v, 6, 'pi' + i));
  near(pi.reduce((a, b) => a + b, 0), 1, 12, 'sum');
  // Brute force on a tiny case: every 8-bit string, template 11, K = 3.
  const counts = [0, 0, 0, 0];
  for (let v = 0; v < 256; v++) {
    let c = 0;
    for (let i = 0; i < 7; i++) if (((v >> i) & 3) === 3) c++;
    counts[Math.min(c, 3)]++;
  }
  assert.deepStrictEqual(N.overlappingProbabilities([1, 1], 8, 3).map((p) => p * 256), counts);
});

test('2.8 overlapping template matching (first 1,000,000 bits of e)', () => {
  // The publication's worked example (2.8.8) uses the reference code's approximate
  // probabilities: 'reference' reproduces it exactly.
  const ref = N.overlappingTemplate(E1M, 9, 1032, 5, null, { probabilities: 'reference' });
  assert.deepStrictEqual(ref.stats.nu, [329, 164, 150, 111, 78, 136]);
  near(ref.stats.chi2, 8.965859);
  near(ref.pValues[0], 0.110434);
  // Same counts with the exact probabilities of section 3.8 (the default).
  const r = N.overlappingTemplate(E1M, 9, 1032, 5);
  assert.deepStrictEqual(r.stats.nu, ref.stats.nu);
  near(r.stats.chi2, 7.949564);
  near(r.pValues[0], 0.159037);
});

test('2.9 Maurer universal statistical test', () => {
  near(N.universal(S('01011010011101010111'), 2, 4).stats.fn, 1.1949875, 7);
  const r = N.universal(E1M);
  assert.deepStrictEqual([r.stats.L, r.stats.Q], [7, 1280]);
  near(r.pValues[0], 0.282568);
});

test('2.10 linear complexity (first 1,000,000 bits of e, M = 1000)', () => {
  assert.strictEqual(N.berlekampMassey(S('1101011110001')), 4);
  const r = N.linearComplexity(E1M, 1000);
  assert.deepStrictEqual(r.stats.nu, [11, 31, 116, 501, 258, 57, 26]);
  near(r.stats.chi2, 2.700348);
  near(r.pValues[0], 0.845406);
});

test('2.11 serial', () => {
  const s = N.serial(S('0011011101'), 3);
  assert.deepStrictEqual(s.stats.psi2.map((v) => +v.toFixed(6)), [2.8, 1.2, 0.4]);
  near(s.pValues[0], 0.808792);
  near(s.pValues[1], 0.670320);
  const r = N.serial(E1M, 2);
  near(r.stats.del1, 0.339764);
  near(r.stats.del2, 0.336400);
  near(r.pValues[0], 0.843764);
  near(r.pValues[1], 0.561915);
});

test('2.12 approximate entropy', () => {
  const s = N.approximateEntropy(S('0100110101'), 3);
  near(s.stats.apEn, 0.190954);
  near(s.pValues[0], 0.261961);
  const r = N.approximateEntropy(pi(100), 2);
  near(r.stats.apEn, 0.665393);
  near(r.stats.chi2, 5.550792);
  near(r.pValues[0], 0.235301);
});

test('2.13 cumulative sums', () => {
  const s = N.cumulativeSums(S('1011010111'));
  assert.strictEqual(s.stats.zForward, 4);
  near(s.pValues[0], 0.411659);
  const r = N.cumulativeSums(pi(100));
  assert.deepStrictEqual([r.stats.zForward, r.stats.zReverse], [16, 19]);
  near(r.pValues[0], 0.219194);
  near(r.pValues[1], 0.114866);
});

test('2.14 random excursions (first 1,000,000 bits of e)', () => {
  const r = N.randomExcursions(E1M);
  assert.strictEqual(r.stats.J, 1490);
  const chi2 = [3.835698, 7.318707, 7.861927, 15.692617, 2.430872, 4.798906, 2.357041, 2.488767];
  const p = [0.573306, 0.197996, 0.164011, 0.007779, 0.786868, 0.440912, 0.797854, 0.778186];
  r.stats.states.forEach((x, i) => { near(r.stats.chi2[i], chi2[i], 6, 'x=' + x); near(r.pValues[i], p[i], 6, 'x=' + x); });
  // The publication's 10-bit example (J = 3, x = +1) prints chi2 = 4.333033; exact arithmetic gives 13/3.
  const small = N.randomExcursions(S('0110110101'));
  assert.strictEqual(small.stats.J, 3);
  assert.deepStrictEqual(small.stats.visits[4], [1, 1, 0, 1, 0, 0]);
  near(small.stats.chi2[4], 13 / 3, 12);
});

test('2.15 random excursions variant (first 1,000,000 bits of e)', () => {
  const r = N.randomExcursionsVariant(E1M);
  assert.strictEqual(r.stats.J, 1490);
  assert.deepStrictEqual(r.stats.xi, [1450, 1435, 1380, 1366, 1412, 1475, 1480, 1468, 1502, 1409, 1369, 1396, 1479, 1599, 1628, 1619, 1620, 1610]);
  const p = [0.858946, 0.794755, 0.576249, 0.493417, 0.633873, 0.917283, 0.934708, 0.816012, 0.826009, 0.137861, 0.200642, 0.441254];
  p.forEach((v, i) => near(r.pValues[i], v, 6, 'x=' + r.stats.states[i]));
  const small = N.randomExcursionsVariant(S('0110110101'));
  assert.strictEqual(small.stats.xi[9], 4);
  near(small.pValues[9], 0.683091);
});

test('runNist applies size limits and marks short inputs not applicable', () => {
  const short = N.runNist(pi(1000));
  const byId = Object.fromEntries(short.results.map((r) => [r.id, r]));
  assert.strictEqual(byId.frequency.applicable, true);
  assert.strictEqual(byId.matrixRank.applicable, false);
  assert.strictEqual(byId.randomExcursions.applicable, false);
  const full = N.runNist(E1M);
  assert.strictEqual(full.results.length, 15);
  assert.ok(full.results.every((r) => r.applicable), JSON.stringify(full.results.filter((r) => !r.applicable)));
  // As in the publication's example, state x = -1 of the random excursions test gives
  // P = 0.007779 < 0.01 for e; every other test passes.
  assert.deepStrictEqual(full.results.filter((r) => !r.pass).map((r) => r.id), ['randomExcursions']);
  // One P-value below 0.01 among ~160 is expected by chance: flagged, not failed.
  assert.strictEqual(full.results.find((r) => r.id === 'randomExcursions').status, 'flag');
  assert.strictEqual(full.family.pass, true);
  assert.ok(full.family.pValueCount > 150, String(full.family.pValueCount));
  const zeros = N.runNist(new Uint8Array(1000000));
  assert.ok(zeros.results.filter((r) => r.applicable).every((r) => !r.pass), 'all-zero input must fail');
  assert.ok(zeros.results.filter((r) => r.applicable).every((r) => r.status === 'fail'), 'all-zero input must fail the family test');
  assert.strictEqual(zeros.family.pass, false);
});

test('binomial tail and Holm', () => {
  near(N.binomialUpperTail(4, 100, 0.01), 0.018374, 6);
  assert.strictEqual(N.binomialUpperTail(0, 10, 0.3), 1);
  near(N.binomialUpperTail(10, 10, 0.5), 2 ** -10, 15);
  assert.deepStrictEqual(N.holm([0.001, 0.02, 0.04], 0.05), [true, true, true]);
  assert.deepStrictEqual(N.holm([0.01, 0.04, 0.03], 0.05), [true, false, false]);
  assert.deepStrictEqual(N.holm([0.2, 0.3], 0.05), [false, false]);
});

// Bits from a fixed xoshiro128** stream: deterministic, no flaky test.
function streamBits(n, seed, p1 = 0.5) {
  const g = new Xoshiro128ss(seed, seed * 7 + 1, seed * 13 + 2, seed * 31 + 3);
  const out = new Uint8Array(n);
  if (p1 === 0.5) { for (let i = 0; i < n; i += 32) { const w = g.nextU32(); for (let j = 0; j < 32 && i + j < n; j++) out[i + j] = (w >>> (31 - j)) & 1; } }
  else for (let i = 0; i < n; i++) out[i] = g.nextU32() / 4294967296 < p1 ? 1 : 0;
  return out;
}

test('family verdict: good random data is not called defective; the per-test rule alone often is', () => {
  let perTestRed = 0, familyFail = 0;
  const runs = 30;
  for (let s = 1; s <= runs; s++) {
    const r = N.runNist(streamBits(400000, s));
    if (r.results.some((t) => t.applicable && !t.pass)) perTestRed++;
    if (!r.family.pass) familyFail++;
    assert.ok(r.results.every((t) => t.status !== 'fail') === r.family.pass);
  }
  // Holm keeps the family error at or below 1% per run.
  assert.ok(familyFail <= 1, `family false alarms ${familyFail}/${runs}`);
  assert.ok(perTestRed >= 2, `per-test rule flagged ${perTestRed}/${runs}`);
});

test('two-level assessment (section 4.2): proportion bound, uniformity and verdict', () => {
  // 96 of 100 passing is outside (1 - 0.01) - 3 sqrt(0.01 * 0.99 / 100) = 0.96015; 97 is inside.
  const ps = (below) => Array.from({ length: 100 }, (_, i) => (i < below ? 0.005 : 0.01 + 0.99 * (i + 0.5) / 100));
  assert.strictEqual(N.secondLevel(ps(4)).proportionOk, false);
  assert.strictEqual(N.secondLevel(ps(3)).proportionOk, true);
  near(N.secondLevel(ps(3)).proportionChance, 0.018374, 6);
  // P-values bunched in one bin fail uniformity.
  const bunched = N.secondLevel(Array.from({ length: 60 }, (_, i) => 0.5 + i / 1000));
  assert.strictEqual(bunched.uniformityOk, false);
  assert.strictEqual(N.secondLevel(ps(0).slice(0, 40)).uniformityP, null); // fewer than 55 sequences

  const good = N.runNistMulti(streamBits(12 * 100000, 99), { sequenceLength: 100000 });
  assert.strictEqual(good.sequences, 12);
  assert.strictEqual(good.family.pass, true);
  const freq = good.results.find((r) => r.id === 'frequency');
  assert.strictEqual(freq.sequences, 12);
  assert.strictEqual(freq.subtests.length, 1);
  // A 52% ones generator fails frequency on nearly every sequence.
  const biased = N.runNistMulti(streamBits(12 * 100000, 5, 0.52), { sequenceLength: 100000 });
  assert.strictEqual(biased.family.pass, false);
  assert.strictEqual(biased.results.find((r) => r.id === 'frequency').status, 'fail');
  assert.throws(() => N.runNistMulti(streamBits(500000, 1), { sequenceLength: 100000 }), /at least 10 sequences/);
});
